-- SifoRestaurant initial schema proposal. Review before applying to any database.
create extension if not exists pgcrypto;
create table if not exists public.companies(id uuid primary key default gen_random_uuid(),name text not null,currency char(3) not null default 'ZMW',created_at timestamptz not null default now());
create table if not exists public.branches(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,created_at timestamptz not null default now(),unique(company_id,name));
create table if not exists public.restaurant_tables(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid not null references public.branches(id) on delete cascade,label text not null,seats int not null default 2 check(seats>0),active boolean not null default true,unique(branch_id,label));
create table if not exists public.menu_items(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,sku text,price numeric(14,2) not null check(price>=0),active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid not null references public.branches(id) on delete cascade,table_id uuid references public.restaurant_tables(id),order_no text not null,order_type text not null check(order_type in('dine_in','takeaway','delivery')),status text not null default 'open' check(status in('open','sent','preparing','ready','served','paid','void')),subtotal numeric(14,2) not null default 0,tax_total numeric(14,2) not null default 0,total numeric(14,2) not null default 0,created_at timestamptz not null default now(),unique(branch_id,order_no));
create table if not exists public.order_lines(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,menu_item_id uuid references public.menu_items(id),description text not null,qty numeric(12,3) not null check(qty>0),unit_price numeric(14,2) not null check(unit_price>=0),line_total numeric(14,2) not null check(line_total>=0));
create table if not exists public.audit_events(id bigint generated always as identity primary key,company_id uuid not null references public.companies(id) on delete cascade,actor_id uuid,action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
